We sort points by x, split at the midpoint, recursively solve each half, then consider pairs that straddle the dividing plane. The strip lives in a slab of width delta along x and is sorted by y. We sweep upward through the strip and only check each point against the next few by y (constant-bounded in 3D because of the geometry). To keep the y-sorting efficient we re-sort the strip at each level. Total cost is O(n log^2 n) for the simpler implementation. This illustrates that the closest-pair divide-and-conquer generalizes to higher dimensions.

```python
import math
from typing import List, Tuple

Point = Tuple[float, float, float]

def closest_pair_3d(points: List[Point]) -> float:
    """Return the closest pairwise 3D Euclidean distance.

    Args:
        points: A list of at least two 3D points.

    Returns:
        The minimum pairwise distance.

    Examples:
        >>> closest_pair_3d([(0, 0, 0), (1, 0, 0), (2, 1, 1)])
        1.0
    """
    pts = sorted(points, key=lambda p: p[0])
    def dist(p: Point, q: Point) -> float:
        return math.sqrt(sum((a - b) ** 2 for a, b in zip(p, q)))
    def brute(lo: int, hi: int) -> float:
        d = float('inf')
        for i in range(lo, hi):
            for j in range(i + 1, hi + 1):
                d = min(d, dist(pts[i], pts[j]))
        return d
    def rec(lo: int, hi: int) -> float:
        if hi - lo <= 2:
            return brute(lo, hi)
        mid = (lo + hi) // 2
        mid_x = pts[mid][0]
        d = min(rec(lo, mid), rec(mid + 1, hi))
        strip = [p for p in pts[lo:hi + 1] if abs(p[0] - mid_x) < d]
        strip.sort(key=lambda p: (p[1], p[2]))
        for i in range(len(strip)):
            for j in range(i + 1, len(strip)):
                if (strip[j][1] - strip[i][1]) ** 2 >= d * d:
                    break
                d = min(d, dist(strip[i], strip[j]))
        return d
    return rec(0, len(pts) - 1)
